"""Predeclared, local-only swarming evaluation inputs and evidence records.

This is a fixture harness, not an agent runner or a security sandbox. Acceptance
executes candidate Python in a bounded child process with the operator's rights.
Only use controlled fixture candidates, never arbitrary downloaded programs.
"""

from __future__ import annotations

from contextlib import contextmanager
from datetime import datetime
import hashlib
import json
import math
from pathlib import Path
import re
import subprocess
import sys
import tempfile
from typing import Any, Iterator


PACK_ROOT = Path(__file__).resolve().parent
MANIFEST_SHA256 = "7023c3d1a92ecec845e795b18a4ec687bd5929b40958cd508115170a0ef1b385"
STRATEGIES = {"single_agent", "batch_delegation", "swarm"}


def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _canonical(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")


def verify_pack(pack_root: Path = PACK_ROOT) -> dict[str, Any]:
    """Reject altered manifests, prompts, inputs, references, or acceptance code."""
    manifest_bytes = (pack_root / "manifest.json").read_bytes()
    if _sha256(manifest_bytes) != MANIFEST_SHA256:
        raise ValueError("Fixture manifest integrity mismatch")
    manifest = json.loads(manifest_bytes)
    for relative, expected in manifest["files"].items():
        if _sha256((pack_root / relative).read_bytes()) != expected:
            raise ValueError(f"Fixture integrity mismatch: {relative}")
    return json.loads((pack_root / "scenarios.json").read_text(encoding="utf-8"))


def _scenario(scenario_id: str) -> dict[str, Any]:
    scenarios = verify_pack()
    if scenario_id not in scenarios:
        raise ValueError(f"Unknown fixture: {scenario_id}")
    return scenarios[scenario_id]


def input_revision(scenario_id: str) -> str:
    """Return the identity of the complete declared input, including its prompt."""
    scenario = _scenario(scenario_id)
    return _sha256(_canonical({key: scenario[key] for key in ("prompt", "seed")}))


def snapshot(project: Path) -> str:
    """Hash all candidate files; generated bytecode is disabled by the verifier."""
    return _sha256(_canonical({
        path.relative_to(project).as_posix(): _sha256(path.read_bytes())
        for path in sorted(project.rglob("*")) if path.is_file()
    }))


@contextmanager
def materialize(scenario_id: str, *, reference: bool = False) -> Iterator[Path]:
    """Create only a fresh temporary project; remove it when the scope exits.

    Reference solutions are fixture self-test oracles. Never expose them to the
    agent being measured or label their execution as a baseline/model run.
    """
    scenario = _scenario(scenario_id)
    files = dict(scenario["seed"])
    if reference:
        files.update(json.loads((PACK_ROOT / "references.json").read_text(
            encoding="utf-8"))[scenario_id])
    with tempfile.TemporaryDirectory(prefix=f"sonn-swarm-{scenario_id}-") as directory:
        root = Path(directory)
        for relative, content in files.items():
            target = root / relative
            if not target.resolve().is_relative_to(root.resolve()):
                raise ValueError("Fixture path escapes temporary project")
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(content.encode("utf-8"))
        yield root


def evaluate(scenario_id: str, project: Path, *, timeout: float = 15) -> dict[str, Any]:
    """Run trusted external checks against an exact candidate snapshot.

    All source-preservation and behavior checks run outside the editable project.
    A timeout/crash is failed evidence, never an accepted artifact. Timing here
    measures verification only, not the time taken by an agent to solve a task.
    """
    scenario = _scenario(scenario_id)
    revision = snapshot(project)
    command = [sys.executable, "-I", "-B", str(PACK_ROOT / "acceptance.py"),
               scenario_id, str(project.resolve())]
    def failed_checks(detail: str) -> list[dict[str, Any]]:
        return [{"name": name, "passed": False, "detail": detail} for name in scenario["checks"]]

    try:
        completed = subprocess.run(command, capture_output=True, text=True,
                                   encoding="utf-8", timeout=timeout, check=False)
        checks = json.loads(completed.stdout) if completed.returncode == 0 else failed_checks(
            f"Not completed: verifier exit={completed.returncode}; {completed.stderr[-2000:]}")
    except subprocess.TimeoutExpired:
        checks = failed_checks("Not completed: verifier timed out")
    except json.JSONDecodeError:
        checks = failed_checks("Not completed: verifier did not return valid JSON")
    checks.append({"name": "candidate_unchanged_during_verification",
                   "passed": snapshot(project) == revision, "detail": "snapshot comparison"})
    return {
        "scenario_id": scenario_id, "input_revision": input_revision(scenario_id),
        "candidate_revision": revision, "manifest_sha256": MANIFEST_SHA256,
        "verifier_sha256": _sha256((PACK_ROOT / "acceptance.py").read_bytes()),
        "checks": checks, "accepted": bool(checks) and all(c["passed"] for c in checks),
    }


def validate_run_record(record: dict[str, Any]) -> None:
    """Validate required pilot facts without inventing missing usage or outcomes.

    A run record is operator-reported metadata, not authenticated provider or
    supervisor evidence. Verification must be supplied by ``evaluate``; local
    hashes identify content and do not establish trusted execution.
    """
    required = {"schema_version", "run_id", "scenario_id", "strategy", "input_revision",
                "manifest_sha256", "prompt", "client_revision", "configuration",
                "usage", "interventions", "timing", "outcome", "verification"}
    if set(record) != required or record["schema_version"] != 1:
        raise ValueError("Run record has missing/unknown fields or unsupported schema")
    scenario = _scenario(record["scenario_id"])
    if record["strategy"] not in STRATEGIES:
        raise ValueError("Unknown execution strategy")
    if (record["input_revision"] != input_revision(record["scenario_id"])
            or record["manifest_sha256"] != MANIFEST_SHA256
            or record["prompt"] != scenario["prompt"]):
        raise ValueError("Run does not use the declared input revision and prompt")
    for field in ("run_id", "client_revision"):
        if not isinstance(record[field], str) or not record[field].strip():
            raise ValueError(f"Missing {field}")
    config = record["configuration"]
    required_config = {"actors", "tool_settings", "permission_settings", "worker_slots",
                       "total_request_concurrency", "resource_control", "limits", "platform"}
    if set(config) != required_config:
        raise ValueError("Incomplete run configuration")
    if config["resource_control"] not in {"operational", "equal_resource"}:
        raise ValueError("Declare the resource comparison control")
    for field in ("worker_slots", "total_request_concurrency"):
        value = config[field]
        if type(value) is not int or value < (1 if field == "total_request_concurrency" else 0):
            raise ValueError(f"Invalid {field}")
    if not isinstance(config["actors"], list) or not config["actors"]:
        raise ValueError("Declare all coordinator and worker model configurations")
    for actor in config["actors"]:
        if set(actor) != {"role", "provider", "model", "parameters"} or any(
            not isinstance(actor[key], str) or not actor[key].strip()
            for key in ("role", "provider", "model")
        ) or not isinstance(actor["parameters"], dict):
            raise ValueError("Incomplete actor model/provider configuration")
    for field in ("tool_settings", "permission_settings", "limits", "platform"):
        if not isinstance(config[field], dict) or not config[field]:
            raise ValueError(f"Declare {field} explicitly")
    usage = record["usage"]
    if set(usage) != {"known", "reserved", "uncertain", "provider_failures"}:
        raise ValueError("Usage must separate known, reserved, and uncertain quantities")
    for bucket in ("known", "reserved", "uncertain"):
        if set(usage[bucket]) != {"requests", "input_tokens", "output_tokens", "cost_usd", "source"}:
            raise ValueError(f"Incomplete usage bucket: {bucket}")
        if not isinstance(usage[bucket]["source"], str) or not usage[bucket]["source"].strip():
            raise ValueError("Usage needs a source or reason it is unavailable")
        for key in ("requests", "input_tokens", "output_tokens", "cost_usd"):
            value = usage[bucket][key]
            if value is not None and (type(value) not in (int, float)
                                       or not math.isfinite(value) or value < 0):
                raise ValueError("Usage is nonnegative or null when unknown")
    if not isinstance(usage["provider_failures"], list):
        raise ValueError("Provider failures must be retained")
    if not isinstance(record["interventions"], list):
        raise ValueError("Operator interventions must be retained")
    for item in record["interventions"]:
        if set(item) != {"at", "kind", "detail"} or not all(
            isinstance(value, str) and value.strip() for value in item.values()
        ):
            raise ValueError("Interventions need timestamp, kind, and detail")
        _timestamp(item["at"])
    timing = record["timing"]
    if set(timing) != {"started_at", "finished_at", "verified_at", "elapsed_seconds"}:
        raise ValueError("Incomplete timing")
    start = _timestamp(timing["started_at"])
    finish = _timestamp(timing["finished_at"])
    seconds = timing["elapsed_seconds"]
    if (finish < start or type(seconds) not in (int, float)
            or not math.isfinite(seconds) or seconds < 0):
        raise ValueError("Invalid elapsed time")
    outcome = record["outcome"]
    if outcome not in {"accepted", "failed", "interrupted", "blocked"}:
        raise ValueError("Invalid outcome")
    evidence = record["verification"]
    if evidence is not None:
        expected = {"scenario_id", "input_revision", "candidate_revision", "manifest_sha256",
                    "verifier_sha256", "checks", "accepted"}
        if (set(evidence) != expected or evidence["scenario_id"] != record["scenario_id"]
                or evidence["input_revision"] != record["input_revision"]
                or evidence["manifest_sha256"] != MANIFEST_SHA256
                or evidence["verifier_sha256"] != _sha256((PACK_ROOT / "acceptance.py").read_bytes())
                or not isinstance(evidence["checks"], list) or not evidence["checks"]):
            raise ValueError("Invalid verification receipt")
        for check in evidence["checks"]:
            if (set(check) != {"name", "passed", "detail"}
                    or type(check["passed"]) is not bool
                    or not isinstance(check["name"], str) or not isinstance(check["detail"], str)):
                raise ValueError("Invalid verification check")
        required_checks = {*scenario["checks"], "candidate_unchanged_during_verification"}
        names = [check["name"] for check in evidence["checks"]]
        if set(names) != required_checks or len(names) != len(required_checks):
            raise ValueError("Verification must contain every declared check exactly once")
        if (not isinstance(evidence["candidate_revision"], str)
                or re.fullmatch(r"[0-9a-f]{64}", evidence["candidate_revision"]) is None):
            raise ValueError("Verification needs an exact candidate content revision")
        if (type(evidence["accepted"]) is not bool
                or evidence["accepted"] != all(check["passed"] for check in evidence["checks"])):
            raise ValueError("Accepted state contradicts checks")
    if timing["verified_at"] is not None and (
        evidence is None or _timestamp(timing["verified_at"]) < start
        or _timestamp(timing["verified_at"]) > finish
    ):
        raise ValueError("Verification timestamp must be inside the measured run")
    if outcome == "accepted" and (evidence is None or not evidence["accepted"]
                                   or timing["verified_at"] is None):
        raise ValueError("Accepted outcome requires passing checks and verification time")


def _timestamp(value: str) -> datetime:
    result = datetime.fromisoformat(value)
    if result.tzinfo is None:
        raise ValueError("Timestamps must contain a timezone")
    return result
